//! Integration test for the multi-instance-column Halo2 KZG/BN254 v1 fixture.
//!
//! Exercises the public C ABI in `rust_crypto_ffi::halo2` against
//! `tests/fixtures/halo2_kzg_bn254_multi_v1.hex`, which is generated by
//! `examples/halo2_fixture_multi.rs` (K = 10, 2 advice columns, 2 instance
//! columns with 2 public values each).

use rust_crypto_ffi::halo2::{
    rustcrypto_halo2_kzg_bn254_instances_validate, rustcrypto_halo2_kzg_bn254_params_validate,
    rustcrypto_halo2_kzg_bn254_verify, rustcrypto_halo2_kzg_bn254_vk_validate,
};

const FIXTURE: &str = include_str!("../../tests/fixtures/halo2_kzg_bn254_multi_v1.hex");

const RUSTCRYPTO_OK: i32 = 0;
const RUSTCRYPTO_ERR_VERIFICATION_FAILED: i32 = 8;
const RUSTCRYPTO_ERR_INVALID_PROOF_FORMAT: i32 = 22;

fn unhex(text: &str) -> Vec<u8> {
    assert!(text.len() % 2 == 0, "odd-length fixture value");
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).expect("invalid fixture hex"))
        .collect()
}

fn fixture_value(name: &str) -> Vec<u8> {
    FIXTURE
        .lines()
        .find_map(|line| line.strip_prefix(&format!("{name}=")))
        .map(unhex)
        .unwrap_or_else(|| panic!("missing fixture value {name}"))
}

fn verify(params: &[u8], vk: &[u8], proof: &[u8], instances: &[u8]) -> i32 {
    rustcrypto_halo2_kzg_bn254_verify(
        params.as_ptr(),
        params.len(),
        vk.as_ptr(),
        vk.len(),
        proof.as_ptr(),
        proof.len(),
        instances.as_ptr(),
        instances.len(),
    )
}

fn u32_be(bytes: &[u8], offset: usize) -> u32 {
    u32::from_be_bytes(bytes[offset..offset + 4].try_into().expect("4-byte field"))
}

#[test]
fn multi_instance_fixture_layout_and_verification() {
    let params = fixture_value("PARAMS");
    let vk = fixture_value("VK");
    let proof = fixture_value("PROOF");
    let instances = fixture_value("INSTANCES");

    assert_eq!(
        rustcrypto_halo2_kzg_bn254_params_validate(params.as_ptr(), params.len()),
        RUSTCRYPTO_OK
    );
    assert_eq!(
        rustcrypto_halo2_kzg_bn254_vk_validate(vk.as_ptr(), vk.len()),
        RUSTCRYPTO_OK
    );
    assert_eq!(
        rustcrypto_halo2_kzg_bn254_instances_validate(instances.as_ptr(), instances.len()),
        RUSTCRYPTO_OK
    );

    // v1 instances layout: magic (8) | column_count (u32 BE).
    assert_eq!(&instances[..8], b"RCH2I1\0\0");
    let column_count = u32_be(&instances, 8) as usize;
    assert_eq!(column_count, 2, "expected two instance columns");

    // Per column: value_count (u32 BE) followed by 32-byte Fr values. Both
    // columns hold two public values, so the payload is 2 * (4 + 2 * 32).
    let mut offset = 12;
    let mut counts = Vec::with_capacity(column_count);
    for _ in 0..column_count {
        let value_count = u32_be(&instances, offset) as usize;
        offset += 4 + value_count * 32;
        counts.push(value_count);
    }
    assert_eq!(
        counts,
        vec![2, 2],
        "expected two values per instance column"
    );
    assert_eq!(offset, instances.len(), "trailing instance bytes");
    assert_eq!(instances.len(), 12 + 2 * (4 + 2 * 32));

    assert_eq!(
        verify(&params, &vk, &proof, &instances),
        RUSTCRYPTO_OK,
        "multi-instance proof should verify"
    );

    let mut wrong = instances.clone();
    *wrong.last_mut().expect("instance value") ^= 1;
    assert_eq!(
        verify(&params, &vk, &proof, &wrong),
        RUSTCRYPTO_ERR_VERIFICATION_FAILED,
        "modified instance value should fail verification"
    );

    let mut trailing = proof.clone();
    trailing.push(0);
    assert_eq!(
        verify(&params, &vk, &trailing, &instances),
        RUSTCRYPTO_ERR_INVALID_PROOF_FORMAT,
        "trailing proof byte should be rejected"
    );
}
